"""Regression test generated by GlitchHunter from a failing run (a live attack on http://127.0.0.1:8000).
Replays the failing schedule: 2 simultaneous POST /withdraw with {'amount': 80}, starting from {'balance': 100}, repeated 20 times
with a 30 ms test pause. It fails if more was taken out than existed, or if the final state does not add up.
Needs the target app running: set GH_TARGET_URL (default http://127.0.0.1:8000). Run with pytest, or: python test_wallet_race.py"""
import os
import sys
import threading

import httpx

BASE = os.environ.get("GH_TARGET_URL", "http://127.0.0.1:8000")
METHOD, PATH, PARAMS = 'POST', '/withdraw', {'amount': 80}
RESET_PATH, RESET_PARAMS, STATE_PATH = '/reset', {'balance': 100, 'stock': 5}, '/state'
N, DELAY, TRIALS = 2, 30, 20
KEY, INITIAL, UNIT = 'balance', 100, 80


def one_trial(cl):
    cl.post(RESET_PATH, params=RESET_PARAMS)
    barrier, statuses = threading.Barrier(N), [None] * N

    def go(i):
        barrier.wait()
        statuses[i] = cl.request(METHOD, PATH, params=PARAMS, headers={"X-Race-Delay": str(DELAY)}).status_code

    threads = [threading.Thread(target=go, args=(i,)) for i in range(N)]
    [t.start() for t in threads]
    [t.join() for t in threads]
    return statuses, cl.get(STATE_PATH).json()[KEY]


def test_no_overdraw_under_concurrency():
    with httpx.Client(base_url=BASE, timeout=30) as cl:
        for trial in range(TRIALS):
            statuses, final = one_trial(cl)
            taken = sum(1 for s in statuses if s == 200) * UNIT
            assert taken <= INITIAL, f"trial {trial}: {taken} was taken out of {INITIAL} (statuses {statuses})"
            assert final == INITIAL - taken, f"trial {trial}: {KEY} ended at {final}, expected {INITIAL - taken} (statuses {statuses})"


if __name__ == "__main__":
    try:
        test_no_overdraw_under_concurrency()
        print("PASS: no violation in 20 simultaneous trials")
    except AssertionError as e:
        print("FAIL:", e)
        sys.exit(1)
